func testTabelaDescontoToManyAddOpTdescEntidades(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a TabelaDesconto
	var b, c, d, e Entidade

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, tabelaDescontoDBTypes, false, strmangle.SetComplement(tabelaDescontoPrimaryKeyColumns, tabelaDescontoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Entidade{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, entidadeDBTypes, false, strmangle.SetComplement(entidadePrimaryKeyColumns, entidadeColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*Entidade{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddTdescEntidades(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.TdescID, first.TdescID) {
			t.Error("foreign key was wrong value", a.TdescID, first.TdescID)
		}
		if !queries.Equal(a.TdescID, second.TdescID) {
			t.Error("foreign key was wrong value", a.TdescID, second.TdescID)
		}

		if first.R.Tdesc != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Tdesc != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.TdescEntidades[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.TdescEntidades[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.TdescEntidades().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

